import { promises as fs } from 'node:fs';for(const p of ['scripts/build.mjs','assets/atlas.css'])await fs.access(p).catch(()=>{throw new Error(`Eksik: ${p}`)});let b=await fs.readFile('scripts/build.mjs','utf8');if(!b.includes('V25.5 Numbered Compass menu entry')){b+='\n'+await fs.readFile('v25-5-build-patch.txt','utf8');await fs.writeFile('scripts/build.mjs',b)}let c=await fs.readFile('assets/atlas.css','utf8');if(!c.includes('V25.5 Menu item 08')){c+='\n'+await fs.readFile('v25-5-css-patch.txt','utf8');await fs.writeFile('assets/atlas.css',c)}console.log('V25.5 kuruldu: Pusula menüde 08 olarak korundu; Android yayın, kart ve başlık hizaları merkezlendi.');
